class Particle {



  prev, pos, spd, acc;



   noiseScaleX ;
   noiseScaleY ;
   noiseScaleZ ;
   n;
   angle;
   life;


  constructor() {
     noiseScaleX = 900;
     noiseScaleY = 900;
     noiseScaleZ = random(100, 200);
     life = 300;




    pos = new PVector(random(350,450), random(200,300));
    spd = new PVector(5,0);
    acc = new PVector(0,0);






  }


  function update2(){

  n = noise(pos.x / noiseScaleX, pos.y / noiseScaleY);
 //angle = map(n*0.1, 0, 5, 0, 10);

  spd  = new PVector(cos(angle),sin(angle));
  spd.add(acc);
  spd.mult(3);
  pos.add(spd);
  angle = angle+0.02;

 life -= 1;



  }

  function display() {
 // strokeWeight(map(life, 0, 1, 0, 2));
    stroke(255);
    ellipse(pos.x, pos.y,random(0.8,1),random(0.8,1));
  }

 isDead(){
    if(life<=0){
      return true;
    }else{
     return false; 
    }
     }

}


class ParticleSystem{

  ArrayList<Particle> p ;
  ArrayList<Particle> p2 ;

  constructor(){

    p = new ArrayList<Particle>();
    p2 = new ArrayList<Particle>();

  }


  function run(){

     for(i = 0 ; i<p.size() ; i++){

    p.get(i).update2();
    p.get(i).display();



    p2.get(i).update2();
    p2.get(i).display();

 if(p.get(i).isDead()){
     p.remove(i);
   }

 }

  }

 function addParticle(){

   p.add(new Particle());
   p2.add(new Particle());





 }

}

